using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

public class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder==",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: EF Core 9 renamed the default discriminator from
        // "Discriminator" to "$type". Existing documents use the old property name,
        // so we must explicitly configure it to preserve compatibility.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Breaking change: EF Core 9 changed the id format from "EntityType|Key"
        // to just "Key". Existing documents still have the compound format, so we
        // opt back in to the old format to keep them accessible.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

public class Session
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

public class CosmosQueryService
{
    // Breaking change: Cosmos DB provider no longer supports synchronous I/O.
    // ToList(), SaveChanges(), etc. now throw InvalidOperationException.
    // All queries and mutations must use async equivalents.

    public async Task<List<Session>> GetSessionsAsync(CosmosDbContext db)
    {
        // Before (BREAKS in EF Core 9):
        //   return db.Sessions.ToList();
        return await db.Sessions.ToListAsync();
    }

    public async Task AddSessionAsync(CosmosDbContext db, Session session)
    {
        // Before (BREAKS in EF Core 9):
        //   db.Sessions.Add(session);
        //   db.SaveChanges();
        db.Sessions.Add(session);
        await db.SaveChangesAsync();
    }
}

